'use strict';

// MODULES //

var exp = require( '@stdlib/math/base/special/exp' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var MAXLOGF = require( '@stdlib/constants/float32/max-ln' );
var polyval = require( './polyval.js' );


// VARIABLES //

var FIVE_EIGHTHS = f32( 0.625 );
var ZERO = f32( 0.0 );
var HALF = f32( 0.5 );
var ONE = f32( 1.0 );
var TWO = f32( 2.0 );


// MAIN //

/**
* Computes the hyperbolic tangent of a single-precision floating-point number.
*
* ## Method
*
* For \\( |x| < 0.625 \\), we use a rational function of the form (Cody and Waite)
*
* ```tex
* x + x^3 \frac{\mathrm{P}(x)}{\mathrm{Q}(x)}
* ```
*
* Otherwise,
*
* ```tex
* \begin{align*}
* \operatorname{tanhf}(x) &= \frac{\operatorname{sinhf}(x)}{\operatorname{coshf}(x)} \\
* &= 1 - \frac{2}{e^{2x} + 1}
* \end{align*}
* ```
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain | # trials | peak    | rms     |
*     |:----------:|:------:|:--------:|:-------:|:-------:|
*     | IEEE       | -2,2   | 100000   | 1.3e-7  | 2.6e-8  |
*
* @param {number} x - input value
* @returns {number} hyperbolic tangent
*
* @example
* var v = tanhf( 0.0 );
* // returns 0.0
*
* @example
* var v = tanhf( 2.0 );
* // returns ~0.964
*
* @example
* var v = tanhf( -2.0 );
* // returns ~-0.964
*
* @example
* var v = tanhf( NaN );
* // returns NaN
*/
function tanhf( x ) {
	var ax;
	var z;

	// Handle +-0 to preserve sign & nan values:
	if ( x === ZERO || isnanf( x ) ) {
		return x;
	}
	if ( x < ZERO ) {
		ax = f32( -x );
	}
	else {
		ax = f32( x );
	}

	if ( ax > f32( HALF * MAXLOGF ) ) {
		if ( x > ZERO ) {
			return ONE;
		}
		return -ONE;
	}
	if ( ax >= FIVE_EIGHTHS ) {
		ax = f32( exp( f32( TWO * ax ) ) );
		z = f32( ONE - f32( TWO / f32( ax + ONE ) ) );
		if ( x < ZERO ) {
			z = -z;
		}
	}
	else {
		z = f32( ax * ax );
		z = f32( f32( f32( polyval( z ) * z ) * x ) + x );
	}
	return z;
}


// EXPORTS //

module.exports = tanhf;
